#include <bitset>
#include <string>
#include <iostream>

int main() {
    std::string s = "HEADER_101100_TRAILER";

    // Start at index 7 ('1'), use 6 characters ('101100')
    // Bitset is 8 bits (N=8)
    std::bitset<8> b1(s, 7, 6);
    // String used: "101100". LSB (index 0) is '0', MSB (index 5) is '1'.
    // Output: 00101100 (Leading two bits zeroed because 6 < 8)
    std::cout << "Substring: " << b1 << "\n";

    // Full string initialization, N=4
    std::bitset<4> b2("110010"); 
    // Only 4 LSBs used: '0010'
    std::cout << "String too long: " << b2 << "\n";
}
